-- Converted: CREATE TABLE kept; INTEGER -> NUMBER(10,0); name mapped per naming map.
-- Reason: Snowflake has no fixed-width integer type; NUMBER(10,0) holds the full Teradata INTEGER range.
CREATE TABLE SALES.RECOVERED_AFTER_ERROR (
    id NUMBER(10,0)
);

-- Converted: CREATE ROLE reader kept as a Snowflake account-level role; unquoted name resolves to READER.
-- Reason: Snowflake supports CREATE ROLE directly; the name is left unquoted per the identifier idiom.
CREATE ROLE reader;

-- Converted: CREATE ROLE operator kept as a Snowflake account-level role; unquoted name resolves to OPERATOR.
-- Reason: Snowflake supports CREATE ROLE directly; the name is left unquoted per the identifier idiom.
CREATE ROLE operator;

-- Converted: CREATE ROLE auditor kept as a Snowflake account-level role; unquoted name resolves to AUDITOR.
-- Reason: Snowflake supports CREATE ROLE directly; the name is left unquoted per the identifier idiom.
CREATE ROLE auditor;

-- Converted: GRANT reader TO analyst -> GRANT ROLE reader TO USER analyst.
-- Reason: Snowflake requires the ROLE and USER keywords when granting a role to a user; the grant is otherwise identical and adds no privileges.
GRANT ROLE reader TO USER analyst;

-- Converted: GRANT operator TO loader -> GRANT ROLE operator TO USER loader.
-- Reason: Snowflake requires the ROLE and USER keywords when granting a role to a user; the grant is otherwise identical and adds no privileges.
GRANT ROLE operator TO USER loader;

