-- Reason: Snowflake has no SET/MULTISET tables, fixed-width integers or primary indexes; NUMBER precision preserves the source value range and scale.
CREATE TABLE SALES.BRANCH (
    branch_id NUMBER(10,0),
    branch_name VARCHAR(80)
);

